function files(){sheet('Browse',`<div class="picker-location">‹ Locations <strong>On My iPhone</strong></div><div class="eyebrow">RECENTS</div>${[['q3-source.pdf','PDF · 428 KB · 3 pages'],['revenue-q3.csv','CSV · 24 KB'],['whiteboard.svg','Image · 12 KB']].map(([n,t])=>`<button class="wide-btn picker-file" data-action="send-file" data-value="${n}">${icon('file')}<span>${n}<small>${t}</small></span><span>›</span></button>`).join('')}`,true);}
function showLocation(){sheet('Current location',`${mapSVG()}<p class="sheet-note">Lucerne station<br>Zentralstrasse 1, Luzern</p><button class="wide-btn secondary" data-action="maps">Open in Maps</button><button class="wide-btn primary" data-action="send-location">Share current location</button>`);}
function quicklook(m){const ext=m.text.split('.').at(-1).toLowerCase();let body;if(ext==='csv')body='<div class="csv-preview"><table><thead><tr><th>Month</th><th>Revenue CHF</th><th>Change</th></tr></thead><tbody><tr><td>July</td><td>42,800</td><td>+6%</td></tr><tr><td>August</td><td>46,200</td><td>+9%</td></tr><tr><td>September</td><td>49,100</td><td>+9%</td></tr></tbody></table></div>';else if(['svg','jpg','png'].includes(ext))body=whiteboard();else body=Array.from({length:m.pages||3},(_,i)=>`<div class="pdf-paper"><span>PILATUS / Q3 2026</span><h2>${['The quarter,<br>in perspective.','Revenue overview','For your review'][i%3]}</h2><div class="rule"></div><p>Revenue grew 8% compared with last year.</p><div class="pdf-bars"><i></i><i></i><i></i><i></i></div><p>Page ${i+1} of ${m.pages||3}</p></div>`).join('');sheet('Quick Look',`<p class="sheet-note">${esc(m.text)} · ${m.size||'212 KB'}</p>${body}<p class="sheet-note">Files are kept 90 days</p>`,true);}
function renderInfo(){contentRoot().innerHTML=nav('Chat info',chat)+`<div class="scroll info-body"><div class="info-profile">${avatar(chat)}<h2>${parent[chat]?esc(state.topics?.[chat]?.title||'Topic'):'Your helper'}</h2></div><div class="setting-block"><button class="setting-row" data-action="chat-voice"><span>Voice replies</span><span>${prefs(chat).voice} ›</span></button><button class="setting-row" data-action="chat-voice"><span>Reply language</span><span>${prefs(chat).language} ›</span></button></div><div class="info-tabs">${['Media','Files','References'].map(t=>`<button data-action="info-tab" data-value="${t}" class="${tab===t?'active':''}">${t}</button>`).join('')}</div><div class="media-grid">${state.messages[chat].filter(m=>m.type==={Media:'photo',Files:'file',References:'link'}[tab]).map(m=>`<button class="wide-btn" data-action="${m.type==='photo'?'view-photo':m.type==='file'?'quicklook':'navigate'}" data-value="${m.type==='link'?m.ticket:m.id}">${m.type==='photo'?whiteboard():esc(m.text)+' ›'}</button>`).join('')||'<p class="empty">Nothing shared yet.</p>'}</div></div>`;}
function toggleRow(key,label){return `<button class="setting-row" data-action="toggle-setting" data-value="${key}" role="switch" aria-checked="${!!state.settings[key]}"><span>${label}</span><span class="ios-toggle ${state.settings[key]?'on':''}" aria-hidden="true"></span></button>`;}
function renderSettings(){contentRoot().innerHTML=nav('Settings')+`<div class="scroll settings-body"><h3>Preferences</h3><div class="setting-block"><button class="setting-row" data-action="global-voice"><span>Voice</span><span>›</span></button></div><h3>Chats</h3><div class="setting-block">${['pilatus','rigi','home'].map(c=>`<button class="setting-row" data-action="chat-info" data-value="${c}"><span>${names[c]}</span><span>›</span></button>`).join('')}</div></div>`;}
function renderVoiceSettings(){const p=scope==='global'?state.settings:prefs(chat);contentRoot().innerHTML=nav(scope==='global'?'Voice':(parent[chat]?(state.topics?.[chat]?.title||'Topic'):'Your helper')+' · Voice',scope==='global'?'settings':'info')+`<div class="scroll settings-body">${scope==='global'?`<div class="setting-block">${actionButton('voice-menu',`<span>Voice replies</span><span>${esc(p.voice)} ⌄</span>`,'','setting-row')}${toggleRow('swiss','I speak Swiss German')}</div><p class="sheet-note">Defaults for all chats</p>`:`<h3>Voice replies</h3><div class="setting-block">${['Auto (long answers)','Always','Never'].map(v=>choice('voice',v,p.voice)).join('')}</div><p class="sheet-note">Applies to ${parent[chat]?(state.topics?.[chat]?.title||'Topic'):'Your helper'}</p><h3>Reply language</h3><div class="setting-block">${['Same as I speak','German','English'].map(v=>choice('language',v,p.language)).join('')}</div><button class="wide-btn" data-action="use-defaults">Use global defaults</button>`}</div>`;}
