function renderPush(){contentRoot().innerHTML=`<div class="lockscreen"><div class="lock-date">Friday, 6 November</div><div class="lock-time">14:02</div><div class="notification"><div class="notification-head"><img src="logo.svg" alt="">orch <span>now</span></div><strong>Pilatus</strong><p>Voice memo · Q3 summary is ready</p><button class="wide-btn" data-action="push-open">Listen ›</button></div></div>`;}
function openContext(id){const f=findMessage(id),original=$('#msg-'+id);if(!f||!original)return;menuMessage=id;const r=original.getBoundingClientRect(),base=$('#overlay').getBoundingClientRect();sheet('Message',`<div class="reaction-bar">${['👍','❤️','😂','😮','🙏','✅'].map(v=>`<button data-action="reaction" data-value="${v}" aria-label="React ${v}">${v}</button>`).join('')}</div><div class="lifted-bubble">${esc(f.m.text||f.m.transcript||'Voice memo')}</div><div class="context-menu">${['Reply','Copy','Share',...(!f.m.mine&&f.m.type==='file'?['Save']:[])].map(v=>`<button data-action="context" data-value="${v}">${v}${icon({Reply:'chat',Copy:'file',Share:'share',Save:'down'}[v])}</button>`).join('')}</div>`);$('#overlay').classList.add('context-overlay');$('.sheet').style.top=Math.max(8,Math.min(r.top-base.top-70,$('#overlay').clientHeight-400))+'px';}
function startRecord(locked=false){if(recording)return;recording={elapsed:0,locked,paused:false,last:Date.now(),c:chat};renderRecording();}
function renderRecording(){const r=recording;if(!r)return;$('#composer').innerHTML=`<div class="recording-panel ${r.locked?'locked':''}">${!r.locked?`<div class="lock-space"><button class="lock-pill" data-action="lock-record" aria-label="Lock recording">${icon('lock')} ↑</button></div><div class="compose-row"><span class="record-dot">●</span><span id="record-time">${fmt(r.elapsed)}</span><span class="slide-cancel">‹ Slide to cancel</span><button class="icon-button mic" data-action="send-record" aria-label="Send voice note">${icon('mic')}</button></div>`:`<div class="compose-row">${btn('cancel-record','Discard recording','trash')}<span id="record-time">${fmt(r.elapsed)}</span>${r.paused?`<button class="play" data-action="preview-record" aria-label="Play recording preview">${icon('play')}</button>`:wave()}${btn(r.paused?'resume-record':'pause-record',r.paused?'Resume recording':'Pause recording',r.paused?'mic':'pause')}${r.paused?`<button class="icon-button mic" data-action="send-record" aria-label="Send voice note">${icon('arrow')}</button>`:''}</div>${r.paused?'<p class="sheet-note">Listen before sending</p>':''}`}<span id="record-left" class="record-left"></span></div>`;}
setInterval(()=>{if(!recording||recording.paused)return;if(!$('#record-time')){recording=null;return;}recording.elapsed+=(Date.now()-recording.last)/1000;recording.last=Date.now();$('#record-time').textContent=fmt(recording.elapsed);if(recording.elapsed>=90)$('#record-left').textContent=fmt(120-recording.elapsed)+' left';if(recording.elapsed>=120){sendRecord();startRecord(true);}},100);
function cancelRecord(){previewAudio.pause();recording=null;renderComposer();}
function sendRecord(){if(!recording)return;const lang=state.ownerSpoke[chat]||(state.settings.swiss?'Swiss German':lastLanguage(chat));previewAudio.pause();recording=null;sendMessage('voice','',{clip:lang==='English'?'me-en-note':'me-de-note',lang,lang_source:state.settings.swiss?'phone-setting':'detected',transcribing:true,transcribeAt:Date.now()+1800});}
function jumpTo(id){const f=$('#messages'),el=$('#msg-'+id);if(f&&el){f.scrollTop=el.offsetTop-f.offsetTop-30;el.classList.add('highlight');readVisible();}}
async function copyText(t){try{await navigator.clipboard.writeText(t);toast('Copied');}catch{sheet('Copy text',`<textarea class="caption-input" aria-label="Text to copy">${esc(t)}</textarea>`);}}
async function shareMessage(id){const m=findMessage(id)?.m,text=m?.text||m?.transcript||'Voice memo';if(navigator.share){try{await navigator.share({title:'orch',text});return;}catch(e){if(e.name==='AbortError')return;}}sheet('Share',`<p>${esc(text)}</p><button class="wide-btn" data-action="copy-share" data-value="${esc(text)}">Copy</button>`);}
function saveFile(m){let data,type;const ext=m.text.split('.').at(-1);if(ext==='csv'){data='Month,Revenue CHF,Change\nJuly,42800,+6%\nAugust,46200,+9%\nSeptember,49100,+9%';type='text/csv';}else if(ext==='svg'){data=whiteboard();type='image/svg+xml';}else{ // A valid, deliberately small local PDF matching the Quick Look figures.
 const stream='BT /F1 20 Tf 50 750 Td (Pilatus Q3 - Revenue grew 8 percent) Tj ET';const objects=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R] /Count 1 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',`<< /Length ${stream.length} >>\nstream\n${stream}\nendstream`];data='%PDF-1.4\n';const offsets=[0];objects.forEach((s,i)=>{offsets.push(data.length);data+=`${i+1} 0 obj\n${s}\nendobj\n`;});const xref=data.length;data+=`xref\n0 6\n0000000000 65535 f \n${offsets.slice(1).map(n=>String(n).padStart(10,'0')+' 00000 n \n').join('')}trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;type='application/pdf';}
 const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=m.text;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function review(key){if(recording&&!['record','locked'].includes(key))cancelRecord();if(names[key]||['chats','settings','push'].includes(key)){navigate(key);if(key==='settings'){scope='global';screen='voice-settings';render();}}else if(key==='info'){navigate('info');}else{if(screen!=='chat')navigate('pilatus');if(key==='composer'){state.drafts[chat]='Please add a short summary';renderComposer();$('#message-input').focus();}if(key==='record'){cancelRecord();startRecord();}if(key==='locked'){cancelRecord();startRecord(true);}if(key==='attach')attach();if(key==='camera')camera();if(key==='preview')preview();if(key==='location')showLocation();if(key==='files')files();if(key==='offline'){navigate('pilatus');setOffline(true);if(!state.messages.pilatus.some(m=>m.demoQueue)){sendMessage('text','Please check these when you’re back.',{demoQueue:true});sendMessage('voice','',{demoQueue:true,clip:'me-de-note',lang:'Swiss German',transcript:transcripts['me-de-note']});sendMessage('photo','The board notes.',{demoQueue:true,upload:15});}scrollBottom();}}updateReview(key);}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;if(Date.now()<ignoreClickUntil&&el.closest('#phone'))return;const a=el.dataset.action,v=el.dataset.value,f=findMessage(v),m=f?.m;
 switch(a){
 case 'review':review(v);break;case 'navigate':navigate(v);break;case 'search':revealSearch();$('#search').focus();break;case 'expand':opened.has(v)?opened.delete(v):opened.add(v);renderChats();renderMini();break;case 'filter':filter=v;renderChats();renderMini();break;
 case 'send':sendText();break;case 'mic':toast('Hold to record');break;case 'bottom':scrollBottom();break;case 'cancel-reply':reply=null;renderComposer();break;case 'quote':jumpTo(v);break;
 case 'attach':attach();break;case 'close':closeModal();break;case 'camera':camera();break;case 'scan':camera(true);break;case 'scan-preview':sheet('Document scan',`<div class="pdf-paper"><h2>Meeting notes</h2><p>Q3 board review</p></div><button class="wide-btn primary" data-action="send-file" data-value="scanned-notes.pdf">Send PDF</button>`);break;
 case 'photos':sheet('Photos',`<div class="media-grid"><button data-action="preview" aria-label="Whiteboard photo">${whiteboard()}</button><button data-action="preview" aria-label="Board notes photo">${whiteboard(true)}</button></div>`);break;case 'preview':preview();break;
 case 'send-photo':{const t=$('#caption').value;closeModal();sendMessage('photo',t,{upload:0});break;}
 case 'files':files();break;case 'send-file':closeModal();sendMessage('file',v,{upload:0,size:v.endsWith('.csv')?'24 KB':'428 KB',pages:v.endsWith('.pdf')?3:undefined});break;case 'cancel-upload':m.cancelled=true;m.upload=undefined;persist();refreshMessages();break;
 case 'quicklook':quicklook(m);break;case 'view-photo':sheet('Photo',`<div class="photo">${whiteboard()}</div><p>${esc(m?.text||'')}</p>`,true);break;case 'location':showLocation();break;case 'send-location':closeModal();sendMessage('location','Lucerne station',{lat:47.0502,lon:8.3101,label:'Lucerne station'});break;case 'maps':sheet('Maps',`${mapSVG()}<h3>Lucerne station</h3><p class="sheet-note">Zentralstrasse 1, Luzern<br>47.0502, 8.3101</p>`,true);break;
 case 'play':await playMemo(v);break;case 'speed':speed=speed===1?1.5:speed===1.5?2:1;audio.playbackRate=speed;$$('.speed').forEach(b=>b.textContent=speed+'×');break;case 'transcript':m.expanded=!m.expanded;persist();refreshMessages();break;
 case 'language':sheet('Not right?',`<p class="sheet-note">Choose the language you spoke.</p>${['German','English','Swiss German'].map(l=>`<button class="wide-btn" data-action="correct-language" data-value="${v}" data-language="${l}">${l}</button>`).join('')}`);break;
 case 'correct-language':m.lang=el.dataset.language;m.lang_source='corrected';m.clip=m.lang==='English'?'me-en-note':'me-de-note';m.transcribing=true;m.transcribeAt=Date.now()+1800;state.ownerSpoke[f.c]=m.lang;persist();closeModal();refreshMessages();break;
 case 'edit':if(m.state==='seen'){toast('This message has been seen.');break;}sheet('Edit transcript',`<textarea id="edit-text" class="caption-input" rows="5" aria-label="Transcript">${esc(m.transcript||transcripts[m.clip])}</textarea><button class="wide-btn primary" data-action="save-edit" data-value="${v}">Save</button>`);break;
 case 'save-edit':if(m.state==='seen')toast('This message has been seen.');else{m.transcript=$('#edit-text').value;persist();}closeModal();refreshMessages();break;
 case 'mini-play':if(activeVoice)playMemo(activeVoice.id);break;case 'mini-open':{const active=activeVoice;navigate(active.c);jumpTo(active.id);break;}case 'mini-close':audio.pause();activeVoice=null;renderMini();break;
 case 'answer':if(m.type==='allow'&&!online())break;state.answers[v]={value:el.dataset.answer,until:Date.now()+5000,queued:true};persist();refreshMessages();break;case 'undo':if(state.answers[v]?.until>Date.now()){delete state.answers[v];persist();refreshMessages();}break;
 case 'info':navigate('info');break;case 'chat-info':chat=v;navigate('info');break;case 'info-tab':tab=v;renderInfo();renderMini();break;case 'global-voice':scope='global';navigate('voice-settings');break;case 'chat-voice':scope='chat';navigate('voice-settings');break;
 case 'choice':if(scope==='global')state.settings[el.dataset.key]=v;else(state.chatSettings[chat]||={})[el.dataset.key]=v;persist();renderVoiceSettings();renderMini();break;case 'toggle-setting':state.settings[v]=!state.settings[v];persist();renderVoiceSettings();renderMini();break;case 'use-defaults':delete state.chatSettings[chat];persist();renderVoiceSettings();renderMini();break;
 case 'context-open':openContext(v);break;case 'reaction':findMessage(menuMessage).m.reaction=v;persist();closeModal();refreshMessages();break;
 case 'context':{const item=findMessage(menuMessage).m;closeModal(true);if(v==='Reply'){reply=item;renderComposer();$('#message-input').focus();}if(v==='Copy')copyText(item.text||item.transcript||transcripts[item.clip]);if(v==='Share')shareMessage(item.id);if(v==='Save')saveFile(item);break;}case 'copy-share':copyText(v);break;
 case 'cancel-record':cancelRecord();break;case 'send-record':sendRecord();break;case 'lock-record':if(recording){recording.locked=true;renderRecording();}break;case 'pause-record':recording.paused=true;renderRecording();break;case 'resume-record':previewAudio.pause();recording.paused=false;recording.last=Date.now();renderRecording();break;
 case 'preview-record':if(previewAudio.paused){previewAudio.src=`audio/${(state.ownerSpoke[chat]||lastLanguage(chat))==='English'?'me-en-note':'me-de-note'}.mp3`;previewAudio.play().then(()=>{el.innerHTML=icon('pause');}).catch(()=>toast('Preview audio unavailable'));}else{previewAudio.pause();el.innerHTML=icon('play');}break;
 case 'push-open':navigate('pilatus');jumpTo('p7');playMemo('p7');break;
 case 'next-memo':if(screen!=='chat')navigate('rigi');sendMessage('voice','',{clip:(state.ownerSpoke[chat]||lastLanguage(chat))==='English'?'me-en-note':'me-de-note',lang:state.ownerSpoke[chat]||lastLanguage(chat),transcript:(state.ownerSpoke[chat]||lastLanguage(chat))==='English'?transcripts['me-en-note']:transcripts['me-de-note']});break;
 case 'stale-demo':{setOffline(true);const target=state.messages.ticket.find(m=>m.type==='question');state.answers[target.id]={value:'Separately',queued:true,until:Date.now()+5000,computerAnswered:true};persist();navigate('ticket');toast('Computer-side answer staged for reconnect.');break;}
 case 'late-record':if(screen!=='chat')navigate('pilatus');if(!recording)startRecord(true);recording.elapsed=90;recording.last=Date.now();renderRecording();updateReview('locked');break;
 case 'reset':audio.pause();activeVoice=null;state=structuredClone(defaults);for(const ms of Object.values(state.messages))for(const m of ms)if(m.mine)m.replied=true;runs.clear();phase='';filter='All';query='';searchShown=false;persist();navigate('chats');break;
 }
});
document.addEventListener('input',e=>{if(e.target.dataset.scrub){const id=e.target.dataset.scrub,value=Number(e.target.value)/1000;if(activeVoice?.id===id&&Number.isFinite(audio.duration))audio.currentTime=audio.duration*value;else{const f=findMessage(id);activeVoice={id,c:f.c};audio.src=`audio/${f.m.clip}.mp3`;audio.addEventListener('loadedmetadata',()=>{audio.currentTime=audio.duration*value;updateAudioUI();},{once:true});}updateAudioUI();}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='offline')setOffline(el.checked);if(el.id==='computer'){state.computerOn=!el.checked;persist();connection();}if(el.id==='motion')$('#phone').classList.toggle('reduce-motion',el.checked);if(el.id==='text-size'){$('#phone').classList.remove('large','xl');if(el.value!=='normal')$('#phone').classList.add(el.value);}if(el.id==='owner-language'){state.ownerSpoke[chat]=el.value;persist();}});
// Keep the pointer captured on the stable phone, so replacing the composer never moves capture.
document.addEventListener('pointerdown',e=>{if(e.button!==0)return;const mic=e.target.closest('[data-action="mic"]'),b=e.target.closest('[data-msg]');if(mic){e.preventDefault();gesture={type:'record',x:e.clientX,y:e.clientY,start:Date.now()};$('#phone').setPointerCapture(e.pointerId);startRecord();return;}if(e.target.closest('.drag-handle,.sheet-head')){gesture={type:'sheet',x:e.clientX,y:e.clientY};$('.sheet').style.transition='none';return;}if(b&&!e.target.closest('button,input,a')){gesture={type:'bubble',id:b.dataset.msg,x:e.clientX,y:e.clientY};gesture.timer=setTimeout(()=>{if(gesture){openContext(gesture.id);ignoreClickUntil=Date.now()+400;gesture=null;}},500);}else if(e.target.closest('#chat-list'))gesture={type:'list',x:e.clientX,y:e.clientY};});
document.addEventListener('pointermove',e=>{if(!gesture)return;const dx=e.clientX-gesture.x,dy=e.clientY-gesture.y;if(gesture.type==='record'&&recording&&!recording.locked){if(dx< -85){cancelRecord();gesture=null;ignoreClickUntil=Date.now()+400;}else if(dy< -65){recording.locked=true;renderRecording();}}else if(gesture.type==='sheet'&&dy>0){$('.sheet').style.transform=`translateY(${dy}px)`;}else if(Math.abs(dx)>12||Math.abs(dy)>12)clearTimeout(gesture.timer);});
document.addEventListener('pointerup',e=>{if(!gesture)return;const g=gesture,dx=e.clientX-g.x,dy=e.clientY-g.y;clearTimeout(g.timer);gesture=null;if(g.type==='record'){ignoreClickUntil=Date.now()+400;if(recording&&!recording.locked){if(Date.now()-g.start<250){cancelRecord();toast('Hold to record');}else sendRecord();}}if(g.type==='sheet'){if($('.sheet'))$('.sheet').style.transition='';if(dy>70)closeModal();else if($('.sheet'))$('.sheet').style.transform='';}if(g.type==='list'&&dy>55)revealSearch();if(g.type==='bubble'&&dx>60&&Math.abs(dy)<35){reply=findMessage(g.id).m;renderComposer();}});
document.addEventListener('pointercancel',()=>{if(gesture)clearTimeout(gesture.timer);if(gesture?.type==='record'&&recording&&!recording.locked)cancelRecord();gesture=null;});
document.addEventListener('contextmenu',e=>{const b=e.target.closest('[data-msg]');if(b){e.preventDefault();openContext(b.dataset.msg);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(recording)cancelRecord();else closeModal();}if(e.key==='Enter'&&e.target.matches('[data-msg]'))openContext(e.target.dataset.msg);if(e.key==='Tab'&&modal){const nodes=$$('.sheet button,.sheet input,.sheet textarea,.sheet a').filter(n=>!n.disabled),first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.sheet'))){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
$('#overlay').onclick=e=>{if(e.target===$('#overlay'))closeModal();};
previewAudio.onended=()=>{const b=$('[data-action="preview-record"]');if(b)b.innerHTML=icon('play');};
// Seed messages have already completed; only new messages enter the simulated work queue.
for(const ms of Object.values(state.messages))for(const m of ms){if(!m.mine)continue;if(!m.id.includes('-')&&m.id.length<5)m.replied=true;if(m.replyStarted&&!m.replied)m.replyStarted=false;}
if(new URLSearchParams(location.search).has('phone'))document.body.classList.add('phone-only');
render();
function fitPhone(){if(innerWidth<500||document.body.classList.contains('phone-only'))$('#phone').style.height=(visualViewport?.height||innerHeight)+'px';else $('#phone').style.height='';}
window.visualViewport?.addEventListener('resize',fitPhone);window.addEventListener('resize',fitPhone);fitPhone();
